#!/usr/bin/env python3
import sys
import itertools

def solve(N: int, A: int, B: int, C: int, L: "List[int]"):

    def dfs(cur,a,b,c):
        if cur == N:
            return abs(a-A)+abs(b-B)+abs(c-C) - 30 if min(a,b,c) > 0 else 100000

        cur_l = L[cur]
        nex = cur + 1

        ret0 = dfs(nex,a,b,c)
        ret1 = dfs(nex,a+cur_l,b,c)+10
        ret2 = dfs(nex,a,b+cur_l,c)+10
        ret3 = dfs(nex,a,b,c+cur_l)+10

        return min(ret0,ret1,ret2,ret3)

    print(dfs(0,0,0,0))

    return


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    A = int(next(tokens))  # type: int
    B = int(next(tokens))  # type: int
    C = int(next(tokens))  # type: int
    l = [ int(next(tokens)) for _ in range(N) ]  # type: "List[int]"
    solve(N, A, B, C, l)

if __name__ == '__main__':
    main()
